import { test, expect } from '@playwright/test';

test.describe('Login Form Keyboard Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/login');
  });

  test('should navigate through login form fields using Tab key', async ({ page }) => {
    // Start by focusing on the first input field (username/email)
    await page.keyboard.press('Tab');

    // Verify username field is focused
    const usernameField = page.getByLabel(/username|email/i);
    await expect(usernameField).toBeFocused();

    // Tab to password field
    await page.keyboard.press('Tab');
    const passwordField = page.getByLabel(/password/i);
    await expect(passwordField).toBeFocused();

    // Tab to login button
    await page.keyboard.press('Tab');
    const loginButton = page.getByRole('button', { name: /login|sign in/i });
    await expect(loginButton).toBeFocused();
  });

  test('should submit login form using Enter key', async ({ page }) => {
    const usernameField = page.getByLabel(/username|email/i);
    const passwordField = page.getByLabel(/password/i);

    // Focus and fill username field
    await usernameField.focus();
    await usernameField.fill('testuser@example.com');

    // Tab to password field and fill it
    await page.keyboard.press('Tab');
    await passwordField.fill('password123');

    // Tab to login button and submit with Enter
    await page.keyboard.press('Tab');
    await page.keyboard.press('Enter');

    // Verify navigation occurred (adjust URL based on your app)
    await expect(page).toHaveURL(/dashboard|home|authenticated/i);
  });

  test('should navigate backwards through form fields using Shift+Tab', async ({ page }) => {
    const usernameField = page.getByLabel(/username|email/i);
    const passwordField = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login|sign in/i });

    // Focus on login button
    await loginButton.focus();
    await expect(loginButton).toBeFocused();

    // Shift+Tab to password field
    await page.keyboard.press('Shift+Tab');
    await expect(passwordField).toBeFocused();

    // Shift+Tab to username field
    await page.keyboard.press('Shift+Tab');
    await expect(usernameField).toBeFocused();
  });

  test('should allow typing in form fields after keyboard navigation', async ({ page }) => {
    const usernameField = page.getByLabel(/username|email/i);
    const passwordField = page.getByLabel(/password/i);

    // Navigate to username field using Tab
    await page.keyboard.press('Tab');
    await expect(usernameField).toBeFocused();

    // Type username
    await page.keyboard.type('testuser@example.com');
    await expect(usernameField).toHaveValue('testuser@example.com');

    // Navigate to password field
    await page.keyboard.press('Tab');
    await expect(passwordField).toBeFocused();

    // Type password
    await page.keyboard.type('password123');
    await expect(passwordField).toHaveValue('password123');
  });

  test('should have visible focus indicators on all interactive elements', async ({ page }) => {
    const usernameField = page.getByLabel(/username|email/i);
    const passwordField = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login|sign in/i });

    // Check username field focus
    await usernameField.focus();
    const usernameOutline = await usernameField.evaluate((el) => {
      return window.getComputedStyle(el).outline !== 'none';
    });
    expect(usernameOutline).toBeTruthy();

    // Check password field focus
    await passwordField.focus();
    const passwordOutline = await passwordField.evaluate((el) => {
      return window.getComputedStyle(el).outline !== 'none';
    });
    expect(passwordOutline).toBeTruthy();

    // Check button focus
    await loginButton.focus();
    const buttonOutline = await loginButton.evaluate((el) => {
      return window.getComputedStyle(el).outline !== 'none';
    });
    expect(buttonOutline).toBeTruthy();
  });
});
